// for ASCII 32..126. Do not edit by hand.
const ASCII = [218,333,425,557,532,871,721,223,368,368,433,541,300,332,300,342,502,350,532,532,538,532,530,489,502,532,300,300,541,541,541,506,877,650,598,603,648,555,538,656,691,301,427,654,540,791,653,670,565,670,628,521,627,649,632,921,614,590,560,342,336,342,541,532,400,518,581,494,574,507,343,531,580,280,281,582,286,871,578,545,578,565,441,436,361,567,530,781,568,536,465,338,267,338,541];
const EXTRA = {"’":215,"‘":215,"“":426,"”":426,"…":900,"—":832,"–":532,"·":300,"é":507,"è":507,"ê":507,"á":518,"à":518,"â":518,"í":280,"ó":545,"ö":545,"ü":567,"ñ":578,"ç":494,"É":555};
const FALLBACK = 560; // accented letters and other scripts
const WIDE = 1000; // emoji and other wide symbols

export function charWidthEm(ch) {
  const c = ch.codePointAt(0);
  if (c >= 32 && c < 127) return ASCII[c - 32] / 1000;
  if (ch in EXTRA) return EXTRA[ch] / 1000;
  if (c > 0xffff || (c >= 0x2600 && c <= 0x27bf)) return WIDE / 1000;
  return FALLBACK / 1000;
}

/** Width of a string in em in DM Serif Display, ignoring kerning. */
export function textWidthEm(text) {
  let w = 0;
  for (const ch of text) w += charWidthEm(ch);
  return w;
}
